  const P = list => list.map(a => Object.assign({ story: null, jargon: [], mis: [] }, a));

  MV.ASSETS.push(...P([
  { id: "hb-india-diabetes", type: "concept", domain: "science", region: "india", title: "Why India is called the diabetes capital", value: 5, cue: "a relative's sugar report, sweets at a festival, or why so many Indians get diabetes",
    emoji: "🩸", wiki: "Diabetes",
    fact: "A large ICMR study published in 2023 estimated that about 11% of Indian adults have diabetes and about 15% more have prediabetes. That is roughly 10 crore people with diabetes. Only China has more.",
    why: "Many Indians who look slim still get diabetes. The reason sits in the body itself, not only in sweets.",
    mech: "Insulin is the signal that tells cells to take sugar out of the blood. In type 2 diabetes, cells stop answering that signal well. This is called insulin resistance. Research led by Dr Chittaranjan Yajnik in Pune found a thin-fat pattern in Indians. At the same body weight, Indians carry more fat around the belly and organs and less muscle. That fat around the organs makes insulin resistance worse. Less walking and more refined food add to it. The exact causes are still being studied.",
    models: ["second-order-thinking", "map-vs-territory"],
    q: "Why do so many Indians, even slim ones, get type 2 diabetes?",
    a: "Cells stop responding well to insulin, so sugar stays in the blood. Indians tend to carry more fat around the organs and less muscle at the same weight, the thin-fat pattern, which worsens insulin resistance. Less movement and refined food add to it.",
    chain: [["Insulin tells cells to take sugar from the blood", ["insulin", "signal", "sugar"]], ["In type 2 the cells stop responding", ["resist", "stop responding", "stop answering", "respond"]], ["Indians carry more organ fat at the same weight", ["thin-fat", "thin fat", "belly", "organ", "less muscle", "yajnik"]], ["Less movement and refined food add to it", ["walk", "movement", "refined", "food", "diet"]]],
    mcq: { q: "What is the thin-fat Indian pattern?", o: ["More fat around the organs and less muscle at the same body weight", "Indians burn sugar faster than others", "Indians have smaller stomachs", "Indian blood has less insulin at birth"] },
    bring: "When sugar reports come up: “Indians can be slim outside and fatty inside. That is why diabetes catches people who look fit.”",
    follow: "Do you know anyone with normal weight who was surprised by a diabetes diagnosis?",
    deeper: "In 2004 Dr Yajnik and the British doctor John Yudkin published a photo of themselves. Both had the same BMI of 22. Yudkin had about 9% body fat. Yajnik had about 21%. This became known as the Y-Y paradox. For any question about your own sugar, ask a doctor." },

  { id: "hb-blood-pressure", type: "concept", domain: "science", title: "Blood pressure: the silent number", value: 5, cue: "a BP machine at a chemist, a headache someone blames on BP, or why doctors check it every time",
    emoji: "💓", wiki: "Hypertension",
    fact: "Blood pressure is the push of blood against the walls of your arteries. Around 120 over 80 is normal. Above 140 over 90, measured more than once, is high. The 2023 ICMR study found about one in three Indian adults has high blood pressure, and many do not know it.",
    why: "High blood pressure usually causes no symptoms at all. It quietly damages the heart, brain, kidneys and eyes for years before anything is felt.",
    mech: "The first number is the pressure when the heart squeezes. The second is the pressure when it rests between beats. Arteries are stretchy pipes. With age, salt, extra weight, stress and genes, they become stiffer and narrower. The heart must push harder to move the same blood. The extra force slowly wears the thin walls of small vessels. A worn vessel can burst or block, which is how strokes and kidney damage begin. Because nerves do not feel pressure inside arteries, nothing hurts until the damage is done.",
    models: ["second-order-thinking", "margin-of-safety"],
    q: "What do the two blood pressure numbers mean, and why is high BP called silent?",
    a: "The first number is the pressure when the heart squeezes and the second when it rests. Stiff, narrow arteries make the heart push harder. There are no symptoms, so the extra force wears out small vessels in the brain and kidneys for years before anyone feels it.",
    chain: [["Two numbers: heart squeezing and heart resting", ["squeez", "rest", "two numbers", "120", "80"]], ["Stiff or narrow arteries raise the push", ["stiff", "narrow", "push harder", "arter", "salt"]], ["No symptoms, because arteries do not feel pressure", ["silent", "no symptom", "nothing hurts", "do not feel"]], ["Slow damage to brain, kidneys and heart", ["stroke", "kidney", "wear", "damage", "burst"]]],
    mcq: { q: "Why is high blood pressure called a silent condition?", o: ["It usually causes no symptoms while it damages organs", "It only happens while a person is asleep", "It cannot be measured at home", "It goes away without treatment"] },
    bring: "When someone says they feel fine so their BP must be fine: “High BP has no feeling. That is exactly why it is dangerous. Only the machine knows.”",
    follow: "When did you last get your blood pressure measured?",
    deeper: "The WHO suggests less than 5 grams of salt a day, about one teaspoon. Studies find the average Indian eats around 8 grams or more. Much of it is in pickles, papad, namkeen and packaged food. What to do about your own BP is a question for a doctor." },

  { id: "hb-cholesterol", type: "concept", domain: "science", title: "Cholesterol: LDL and HDL in plain words", value: 4, cue: "a lipid profile report, ghee versus oil debates, or a heart check-up",
    emoji: "🧈", wiki: "Cholesterol",
    fact: "Cholesterol is a waxy fat your body needs to build cell walls and hormones. Your liver makes most of it. It travels in the blood inside carrier particles. LDL particles drop it into artery walls. HDL particles carry it back to the liver.",
    why: "People talk about good and bad cholesterol. It is really the same substance in two kinds of delivery vans going in opposite directions.",
    mech: "Fat does not mix with blood, which is mostly water. So cholesterol is packed inside particles made of protein and fat. LDL, low-density lipoprotein, delivers cholesterol out to tissues. When there is too much LDL, some gets stuck in the inner wall of arteries. The immune system attacks it and a fatty lump called plaque forms. HDL, high-density lipoprotein, picks up spare cholesterol and returns it to the liver. Over decades, high LDL and plaque narrow the arteries that feed the heart and brain.",
    models: ["feedback-loops", "second-order-thinking"],
    q: "What is the difference between LDL and HDL cholesterol?",
    a: "Cholesterol is one waxy fat that travels in carrier particles. LDL carries it out to tissues and too much gets stuck in artery walls as plaque. HDL carries spare cholesterol back to the liver.",
    chain: [["Cholesterol is a needed fat, mostly made by the liver", ["liver", "waxy", "hormone", "cell wall", "needed"]], ["It travels inside carrier particles", ["carrier", "particle", "lipoprotein", "van", "pack"]], ["LDL drops it into artery walls as plaque", ["ldl", "plaque", "stuck", "artery wall"]], ["HDL carries it back to the liver", ["hdl", "back to the liver", "return", "picks up"]]],
    mcq: { q: "What does LDL do that makes it the ‘bad’ one?", o: ["It delivers cholesterol into artery walls where plaque forms", "It stops the liver from making bile", "It thins the blood too much", "It turns sugar into fat"] },
    bring: "When a lipid report is discussed: “Good and bad cholesterol are the same fat. LDL takes it to the arteries, HDL brings it back.”",
    follow: "Did you know your liver makes most of your cholesterol, whatever you eat?",
    deeper: "Plaque can build up from the teens onward. Autopsies of young American soldiers in the Korean War found early plaque in most of them. What your own numbers mean is a conversation for a doctor." },

  { id: "hb-heart-attack", type: "concept", domain: "science", title: "A heart attack is a blocked pipe, not a stopped heart", value: 5, cue: "news of a sudden death, chest pain, or the ‘golden hour’",
    emoji: "🫀", wiki: "Myocardial infarction",
    fact: "A heart attack happens when an artery that feeds the heart muscle gets blocked, usually by a blood clot. The part of the muscle behind the block starts to die within minutes to hours. The heart usually keeps beating during a heart attack.",
    why: "People confuse a heart attack with a cardiac arrest, where the heart stops. Knowing the difference explains why speed matters so much.",
    mech: "Over years, fatty plaque builds inside the heart's arteries. One day a plaque cracks. The body treats the crack like a wound and forms a clot on it. The clot blocks the pipe. Muscle downstream gets no oxygen and begins to die. Doctors say ‘time is muscle’. If the block is opened within about an hour, with clot-dissolving drugs or a stent, most of the muscle can be saved. Warning signs include pressure in the chest, pain spreading to the arm or jaw, sweating and breathlessness, and they can be milder in women and in people with diabetes.",
    models: ["bottlenecks", "margin-of-safety"],
    q: "What actually happens in a heart attack, and why does the first hour matter?",
    a: "Plaque in a heart artery cracks, a clot forms on it and blocks the pipe. The muscle downstream gets no oxygen and starts dying. Opening the block quickly, within about an hour, saves most of the muscle.",
    chain: [["Plaque in a heart artery cracks", ["plaque", "crack", "artery"]], ["A clot forms and blocks the pipe", ["clot", "block", "pipe"]], ["Muscle behind the block starts to die", ["oxygen", "die", "dying", "muscle"]], ["Opening it within about an hour saves muscle", ["hour", "stent", "dissolv", "time is muscle", "quick"]]],
    mcq: { q: "What causes most heart attacks?", o: ["A clot blocking an artery that feeds the heart muscle", "The heart suddenly stopping its electrical signal", "A hole opening in the heart wall", "Blood becoming too thin"] },
    bring: "When someone says a person ‘died of a heart attack in his sleep’: “A heart attack is a blocked pipe. The heart stopping is a cardiac arrest. They are related but not the same.”",
    follow: "Do you know which hospital near you can open a blocked artery at night?",
    deeper: "In a cardiac arrest the heart's electrical rhythm fails and it stops pumping. CPR and a shock from a defibrillator are the treatments. A heart attack can trigger a cardiac arrest, which is why chest pain should mean a hospital, not waiting." },

  { id: "hb-stroke-fast", type: "concept", domain: "science", title: "Stroke and the FAST signs", value: 5, cue: "someone's face suddenly drooping, slurred speech, or ‘brain attack’",
    emoji: "🧠", wiki: "Stroke",
    fact: "A stroke is a heart attack of the brain. Most strokes happen when a clot blocks an artery in the brain. Some happen when a vessel bursts. Brain cells behind the block die fast, so doctors say ‘time is brain’. The FAST test spots it: Face drooping, Arm weakness, Speech trouble, Time to call for help.",
    why: "Every minute of a blocked brain artery kills millions of brain cells. The person who notices the signs first is usually a family member, not a doctor.",
    mech: "The brain uses about a fifth of the body's oxygen but stores almost none. When an artery is blocked, cells in that area stop working within seconds and start dying within minutes. Each part of the brain controls something, so the signs show what is cut off: one side of the face or body, speech, vision or balance. Clot-dissolving drugs work best within about four and a half hours, and clot removal with a thin tube can help for some hours after that. Later, less can be saved.",
    models: ["bottlenecks", "margin-of-safety"],
    q: "What is a stroke and how can an ordinary person recognise one?",
    a: "A clot blocks, or a vessel bursts in, an artery in the brain, and brain cells behind it start dying within minutes. Use FAST: face drooping, arm weakness, speech trouble, time to get help fast, because clot drugs work best within a few hours.",
    chain: [["A brain artery is blocked or bursts", ["clot", "block", "burst", "artery"]], ["Brain cells die within minutes", ["die", "dying", "minutes", "oxygen"]], ["Signs: face, arm, speech", ["face", "arm", "speech", "fast"]], ["Treatment works best within a few hours", ["four", "4.5", "hours", "time", "quick", "fast"]]],
    mcq: { q: "What does the ‘F’ in FAST stand for?", o: ["Face drooping on one side", "Fever rising suddenly", "Fast heartbeat", "Feet going cold"] },
    bring: "When someone describes an uncle whose speech suddenly became strange: “That is a FAST sign. Face, arm, speech. With a stroke the clock starts immediately.”",
    follow: "If someone next to you slurred their words and could not lift an arm, what would you do first?",
    deeper: "Lifting both arms is a good test because a stroke usually affects one side. Smiling shows a droop on one side. High blood pressure is the biggest single risk factor for stroke. Never wait to see if it passes; a short attack that passes, called a TIA, is a warning of a bigger one." },

  { id: "hb-bmi-limits", type: "concept", domain: "science", title: "BMI: a useful number with blind spots", value: 4, cue: "a weighing machine at a station, a fitness app, or ‘am I overweight’",
    emoji: "⚖️", wiki: "Body mass index",
    fact: "BMI is weight in kilograms divided by height in metres, squared. A 70 kg person who is 1.7 m tall has a BMI of about 24. The WHO calls 25 and above overweight. Indian guidelines use lower cut-offs: 23 and above is overweight, 25 and above is obese.",
    why: "BMI was invented in the 1830s by a Belgian astronomer to describe average men, not to judge one person. It is useful for populations and rough for individuals.",
    mech: "Adolphe Quetelet wanted a formula for the ‘average man’. He found weight rose roughly with height squared. A century later insurers and doctors adopted his number as a health screen. But BMI cannot tell fat from muscle, or belly fat from leg fat. A muscular athlete can score as obese. A thin-fat Indian can score as normal while carrying harmful fat around the organs. That is why India lowered its cut-offs, and why waist size is often measured too.",
    models: ["map-vs-territory", "goodharts-law"],
    q: "What is BMI, and what are its limits?",
    a: "BMI is weight divided by height squared, invented by Quetelet to describe average men. It cannot tell muscle from fat or belly fat from other fat, so athletes score high and thin-fat Indians score normal. India uses lower cut-offs and waist size is measured too.",
    chain: [["Weight divided by height squared", ["divided", "height", "squared", "formula"]], ["Made by Quetelet for populations, not persons", ["quetelet", "average man", "astronomer", "population", "1830"]], ["Cannot tell fat from muscle or where fat sits", ["muscle", "fat from", "belly", "athlete", "where"]], ["India uses lower cut-offs and waist size", ["23", "lower cut", "india", "waist"]]],
    mcq: { q: "What is a weakness of BMI?", o: ["It cannot tell muscle from fat", "It needs a blood test", "It only works for children", "It changes with the weather"] },
    bring: "When someone frets about a BMI app: “BMI was made by an astronomer to describe crowds. For one person it is a rough guide, not a verdict.”",
    follow: "Would you rather know your BMI or your waist measurement?",
    deeper: "Indian guidelines from 2009 also suggest a waist above 90 cm for men and 80 cm for women as a risk marker. Belly fat sits around the organs and is more closely tied to diabetes and heart disease than fat under the skin." },

  { id: "hb-crash-diets", type: "scientific principle", domain: "science", title: "Why crash diets usually fail", value: 4, cue: "a friend's new diet, lost weight that came back, or a slimming advertisement",
    emoji: "📉", wiki: "The Biggest Loser",
    fact: "Most people who lose a lot of weight fast regain most of it within a few years. A famous study followed contestants of the TV show The Biggest Loser. They lost about 58 kg on average. Six years later they had regained about 41 kg, and their bodies were burning around 500 fewer calories a day than expected.",
    why: "The body treats sudden weight loss as a famine and fights back. Willpower is working against a very old survival system.",
    mech: "The brain keeps a rough target weight, often called a set point. When food drops sharply, the body lowers its resting energy use, so it burns less even at rest. Hunger hormones rise and fullness hormones fall, so the person feels hungrier than before. Muscle is lost along with fat, and muscle is what burns calories. When normal eating returns, the slowed body stores the extra as fat. The evidence suggests slow changes that can be kept for years work better than fast ones, but how this works for any one person differs.",
    models: ["feedback-loops", "second-order-thinking"],
    q: "Why does weight lost quickly usually come back?",
    a: "The body reads fast weight loss as famine. It lowers resting energy use, raises hunger hormones, and loses muscle. When eating returns to normal the slowed body stores the extra as fat, as the Biggest Loser study showed six years on.",
    chain: [["The body sees fast loss as famine", ["famine", "set point", "target", "fights back"]], ["Resting energy use drops", ["resting", "burn", "slow", "500", "fewer calories"]], ["Hunger rises and muscle is lost", ["hunger", "hormone", "muscle"]], ["Weight returns when eating normalises", ["regain", "come back", "came back", "stores", "returns"]]],
    mcq: { q: "What did the Biggest Loser study find six years after the show?", o: ["Most weight was regained and metabolism stayed slower than expected", "Everyone kept the weight off", "Contestants burned more calories than before", "Only men regained weight"] },
    bring: "When someone starts a very strict diet: “The body thinks it is a famine and slows down. That is why the weight so often comes back.”",
    follow: "Have you seen a slow change that lasted longer than a fast one?",
    deeper: "The set point idea is a simple model and scientists still debate how fixed it is. Sleep, stress and some medicines also change hunger. Anyone planning a big change in diet should talk to a doctor first." },

  { id: "hb-juice-vs-fruit", type: "scientific principle", domain: "science", title: "Why fruit juice is not fruit", value: 4, cue: "a juice stall, a ‘healthy’ breakfast, or sugar in packaged drinks",
    emoji: "🧃", wiki: "Orange juice",
    fact: "A 250 ml glass of orange juice has roughly 20 to 25 grams of sugar, about the same as a glass of cola. It takes three or four oranges to fill that glass. Eating three oranges takes time and fills you up. Drinking the glass takes a minute.",
    why: "The sugar is the same. What changes is the fibre, the speed and how much you take in without noticing.",
    mech: "Whole fruit holds its sugar inside cells wrapped in fibre. Chewing and digestion release it slowly, so blood sugar rises gently. Fibre also fills the stomach and signals fullness. Juicing breaks the cells and throws much of the fibre away. The free sugar hits the blood fast, insulin spikes, and the drink does not make you feel full. Studies link whole fruit with lower diabetes risk and fruit juice with slightly higher risk. Packaged juices often add more sugar on top.",
    models: ["second-order-thinking", "map-vs-territory"],
    q: "Why do nutrition scientists treat fruit juice differently from whole fruit?",
    a: "Whole fruit holds sugar inside fibre, so it is released slowly and fills you up. Juicing removes the fibre, so the same sugar hits the blood fast and you can drink three or four fruits in a minute without feeling full.",
    chain: [["Whole fruit wraps sugar in fibre", ["fibre", "fiber", "cell", "wrap"]], ["Juicing removes fibre and frees the sugar", ["juic", "remove", "throw", "free sugar", "break"]], ["Sugar hits the blood fast", ["fast", "spike", "quick", "blood sugar"]], ["Several fruits in one glass without fullness", ["three", "four", "fill", "full", "glass"]]],
    mcq: { q: "What is the main thing lost when fruit is turned into juice?", o: ["Most of the fibre", "All the vitamin C", "The water", "The sugar"] },
    bring: "At a juice stall: “This glass is three or four oranges with the fibre thrown away. Same sugar as a cola.”",
    follow: "Would you eat four oranges in one sitting? Then why drink them?",
    deeper: "The WHO counts juice sugar as ‘free sugar’, the same as added sugar, and suggests keeping free sugars under 10% of daily energy. Fibre also feeds the bacteria in the gut." },

  { id: "hb-eight-glasses", type: "fact", domain: "science", title: "Eight glasses of water a day: a rule with weak evidence", value: 3, cue: "water reminder apps, someone forcing down bottles of water, or ‘drink more water’",
    emoji: "💧", wiki: "Drinking water",
    fact: "The rule that everyone must drink eight glasses of water a day has no strong scientific basis. A 1945 American nutrition board suggested about 2.5 litres a day, but the next sentence said most of it already comes from food. The second sentence was forgotten.",
    why: "A healthy body has an excellent water meter built in. It is called thirst.",
    mech: "The kidneys balance water very precisely. When blood gets a little concentrated, the brain releases a hormone that tells the kidneys to hold water and makes you thirsty. When you drink too much, urine simply becomes dilute. Roughly a fifth of daily water comes from food, and tea, coffee, dal and milk all count. In Mumbai's heat, or during fever, exercise or diarrhoea, needs rise a lot. Pale yellow urine is a simple sign of enough water. Very old people and small children feel thirst less reliably.",
    models: ["feedback-loops", "map-vs-territory"],
    q: "Where did the eight glasses rule come from, and how does the body really manage water?",
    a: "A 1945 American guideline said about 2.5 litres a day, mostly from food, and the food part was forgotten. The kidneys and a hormone balance water precisely, thirst signals need, and food and drinks like tea all count.",
    chain: [["A 1945 guideline, with the food part forgotten", ["1945", "forgot", "food", "board"]], ["Kidneys and a hormone balance water", ["kidney", "hormone", "balance", "dilute"]], ["Thirst is the body's meter", ["thirst", "meter", "signal"]], ["Needs rise in heat, fever and exercise", ["heat", "fever", "exercise", "diarrhoea", "rise"]]],
    mcq: { q: "What is the evidence for exactly eight glasses of water a day?", o: ["There is no strong evidence for that number", "A large trial proved it in 1945", "The WHO requires it", "It comes from the kidneys' filtering limit"] },
    bring: "When someone forces down a third bottle: “The eight glasses rule came from a 1945 line that said most of it comes from food. Thirst is the better guide.”",
    follow: "Did you know a bowl of dal or a cup of chai counts towards your water?",
    deeper: "Drinking far too much water in a short time can be dangerous, because it dilutes blood sodium. Marathon runners have died of it. People with kidney or heart disease may need to limit fluids, which is a question for their doctor." },

  { id: "hb-fever", type: "scientific principle", domain: "science", title: "Fever is a weapon, not the illness", value: 4, cue: "a child with a temperature, a thermometer reading, or rushing to bring fever down",
    emoji: "🌡️", wiki: "Fever",
    fact: "Normal body temperature is about 37 degrees Celsius. In a fever the brain deliberately raises its target temperature. Fever is not caused by the germ directly. It is the body's own response, and it helps the immune system fight.",
    why: "Fever feels like the enemy. It is actually one of the body's oldest defences, shared with lizards that lie in the sun when infected.",
    mech: "When immune cells detect germs, they release chemical signals. These reach the hypothalamus, the brain's thermostat, and raise its set point. The body then shivers and narrows skin blood vessels to climb to the new target, which is why you feel cold as a fever starts. At a higher temperature, many bacteria and viruses multiply more slowly. White blood cells move and work faster. When the signals fade, the set point drops, you sweat, and the fever breaks. Very high fever, above about 40 degrees, or fever in a baby, needs a doctor.",
    models: ["inversion", "second-order-thinking"],
    q: "Why does the body produce a fever, and why do you shiver when one starts?",
    a: "Immune cells release signals that raise the brain's thermostat set point. The body shivers to climb to the new target. The heat slows many germs and speeds up white blood cells. When the signals fade, you sweat and the fever breaks.",
    chain: [["Immune signals raise the brain's set point", ["set point", "thermostat", "hypothalamus", "signal", "raise"]], ["Shivering climbs to the new target", ["shiver", "cold", "climb", "target"]], ["Heat slows germs and speeds immune cells", ["slow", "multiply", "white blood", "faster", "fight"]], ["Set point drops and you sweat", ["sweat", "breaks", "drops"]]],
    mcq: { q: "What directly causes a fever?", o: ["The brain raising its own temperature set point in response to immune signals", "Heat produced by the germs themselves", "Too much sun", "Blood thickening"] },
    bring: "When a child has a mild fever: “The body raises the temperature on purpose. It slows the germ and speeds the immune cells.”",
    follow: "Did you know lizards give themselves a fever by lying in the sun when they are infected?",
    deeper: "Fever is tiring and uncomfortable, and in some people, such as babies, pregnant women and the elderly, it needs care. Whether and when to lower a fever is a decision for a doctor, not a rule from a card." },

  { id: "hb-painkillers", type: "scientific principle", domain: "science", title: "How painkillers work, and which one we do not understand", value: 4, cue: "a headache tablet, a chemist's counter, or aspirin from willow bark",
    emoji: "💊", wiki: "Analgesic",
    fact: "Common painkillers work in different places. Drugs like aspirin and ibuprofen block an enzyme at the site of injury, so fewer pain chemicals are made. Opioids act on receptors in the brain and spinal cord. Paracetamol, the most used of all, works in a way that scientists still do not fully understand.",
    why: "The most common tablet in Indian homes has been sold since the 1950s, and its exact mechanism is still a research question.",
    mech: "When tissue is hurt, cells make chemicals called prostaglandins. These make nerve endings more sensitive and cause swelling and fever. Aspirin and ibuprofen block the COX enzymes that make prostaglandins, so the signal is weaker at the source. Opioids like morphine fit into receptors in the brain and spinal cord and turn the pain signal down centrally. Paracetamol lowers fever and pain but does little for swelling, and it seems to act mostly in the brain. Each class has its own harms. Too much paracetamol damages the liver, and aspirin-type drugs can harm the stomach and kidneys.",
    models: ["first-principles", "circle-of-competence"],
    q: "How do the main kinds of painkillers work?",
    a: "Aspirin and ibuprofen block the COX enzymes that make prostaglandins at the injury, so less pain signal is made. Opioids act on receptors in the brain and spinal cord. Paracetamol acts mostly in the brain in ways not fully understood.",
    chain: [["Injury releases prostaglandins that sensitise nerves", ["prostaglandin", "chemical", "sensitive", "swelling"]], ["Aspirin and ibuprofen block the COX enzymes", ["cox", "enzyme", "block", "ibuprofen", "aspirin"]], ["Opioids act on brain and spinal cord receptors", ["opioid", "morphine", "receptor", "spinal"]], ["Paracetamol's mechanism is not fully known", ["paracetamol", "not fully", "do not fully", "unknown"]]],
    mcq: { q: "Which common painkiller's exact mechanism is still not fully understood?", o: ["Paracetamol", "Aspirin", "Ibuprofen", "Morphine"] },
    bring: "When someone pops a tablet: “Aspirin works at the injury, morphine works in the brain, and paracetamol we still do not fully understand.”",
    follow: "Did you know aspirin began as a chemical from willow bark?",
    deeper: "The pain-relieving effect of willow bark was known for centuries. Bayer sold a stable form as aspirin in 1899. Paracetamol overdose is one of the most common causes of sudden liver failure, and the gap between a normal dose and a harmful one is smaller than people think. Always follow the dose a doctor or the packet gives." },

  { id: "hb-anaesthesia", type: "scientific principle", domain: "science", title: "Anaesthesia: switching off awareness, mechanism partly unknown", value: 4, cue: "someone's operation, fear of surgery, or ‘they put me to sleep’",
    emoji: "😴", wiki: "Ether Dome",
    fact: "On 16 October 1846, in a Boston hospital, William Morton put a patient to sleep with ether while a surgeon removed a tumour from his neck. The patient felt nothing. Before that day, surgery was done on awake patients held down by assistants.",
    why: "Anaesthesia made modern surgery possible. Yet how these drugs switch off awareness is still only partly understood.",
    mech: "Before 1846, speed was the only mercy. A good surgeon removed a leg in under a minute. Ether and later drugs changed everything. General anaesthetics act on nerve cells across the brain. Many boost the brain's main calming signal and quiet the signals that keep regions talking to each other. Awareness seems to need those regions to work together, and when they fall out of step, consciousness goes. But no single switch has been found. Modern anaesthesia uses several drugs at once: one for sleep, one for pain, one to relax muscles. An anaesthetist watches breathing, heart and blood pressure throughout.",
    models: ["circle-of-competence", "first-principles"],
    q: "What happened in 1846, and what do we know about how anaesthesia works?",
    a: "In 1846 Morton showed ether could make surgery painless. Anaesthetics act on nerve cells across the brain, boosting calming signals and breaking the communication between regions that awareness needs. No single switch has been found, so the mechanism is still partly unknown.",
    chain: [["1846: Morton's ether demonstration in Boston", ["1846", "morton", "ether", "boston"]], ["Drugs boost calming signals in nerve cells", ["calm", "nerve cell", "boost", "quiet"]], ["Brain regions stop working together", ["region", "together", "communicat", "out of step", "talk"]], ["No single switch is known", ["no single", "partly", "not fully", "still"]]],
    mcq: { q: "How was surgery done before 1846?", o: ["On awake patients, as fast as possible", "With patients frozen in ice", "Only on unconscious accident victims", "It was not done at all"] },
    bring: "When someone fears an operation: “Until 1846 surgery was done awake. Anaesthesia is one of the most tested things in medicine, even if we still debate exactly how it works.”",
    follow: "Does it bother you that something so common is not fully understood?",
    deeper: "The room in Massachusetts General Hospital is still called the Ether Dome. Local anaesthetics like the one at the dentist work differently: they block the sodium channels that nerves use to send a signal, so the message never leaves the tooth." },

  { id: "hb-immune-two-arms", type: "scientific principle", domain: "science", title: "The immune system's two arms: fast and smart", value: 4, cue: "why a cold takes a week, why a second infection is milder, or swelling after a cut",
    emoji: "🛡️", wiki: "Immune system",
    fact: "The immune system has two arms. The innate arm is fast but general: skin, mucus, fever and white cells that eat anything foreign. The adaptive arm is slow the first time but precise: it makes antibodies and killer cells tailored to one germ, and it remembers.",
    why: "This explains why a new infection takes about a week to beat, and why the same germ rarely gets you twice.",
    mech: "When a germ enters, the innate arm acts within minutes. Blood vessels widen, which causes redness and swelling. White cells called macrophages swallow germs and raise the alarm. Meanwhile the adaptive arm begins a search. Among billions of B and T cells, a few happen to fit the invader's shape. Those few multiply for several days, then pour out antibodies that tag the germ and killer T cells that destroy infected cells. After victory, memory cells remain for years. Next time, the response starts in days, not a week, often before you feel ill.",
    models: ["first-principles", "compounding"],
    q: "What are the two arms of the immune system and why does a first infection take about a week?",
    a: "The innate arm acts within minutes with general tools like swelling and cells that eat germs. The adaptive arm needs days to find and multiply the few B and T cells that fit the germ, then makes antibodies and memory cells, so next time is faster.",
    chain: [["Innate arm acts within minutes, generally", ["innate", "minutes", "general", "swelling", "macrophage", "eat"]], ["Adaptive arm finds the few cells that fit", ["adaptive", "b and t", "fit", "shape", "search"]], ["Those cells multiply over days and make antibodies", ["multiply", "days", "antibod", "killer"]], ["Memory cells make the next response fast", ["memory", "next time", "remember", "faster"]]],
    mcq: { q: "Why is a second infection with the same germ usually milder?", o: ["Memory cells from the first infection respond much faster", "The germ becomes weaker over time", "The skin becomes thicker", "The body stores extra blood"] },
    bring: "When someone has a swollen cut: “That redness is the fast arm of the immune system. The smart arm takes a few days to arrive.”",
    follow: "Why do you think chickenpox usually comes only once?",
    deeper: "Vaccines work by showing the adaptive arm a harmless piece of a germ, so memory cells exist before the real one arrives. Allergies are the adaptive arm attacking something harmless, like pollen or peanuts." },

  { id: "hb-common-cold", type: "scientific principle", domain: "science", title: "How a cold spreads, and why soap beats it", value: 4, cue: "a sneezing colleague, monsoon colds, or antibiotics for a cold",
    emoji: "🤧", wiki: "Common cold",
    fact: "More than 200 different viruses cause the common cold, most often rhinoviruses. They spread in droplets from coughs and on hands. A typical adult gets two to four colds a year. Antibiotics do nothing against them, because they kill bacteria, not viruses.",
    why: "The most common illness on Earth has no cure, yet one of the best defences costs a few rupees: soap.",
    mech: "An infected person coughs or touches their nose, then a handrail, a lift button or a phone. The virus can survive there for hours. You touch the surface and then your eyes or nose, and the virus enters. Hands carry more colds than air does. Soap and twenty seconds of rubbing lift germs off the skin and wash them away. A cold is self-limiting: the immune system clears it in about a week. Antibiotics target machinery that only bacteria have, so taking them for a cold brings side effects and feeds resistance for no gain.",
    models: ["first-principles", "second-order-thinking"],
    q: "How does a cold usually spread, and why are antibiotics useless against it?",
    a: "The virus travels on droplets and hands, from surfaces to your eyes or nose. Soap and rubbing wash it off. A cold is caused by viruses, and antibiotics only attack bacteria, so they cannot help and add resistance.",
    chain: [["Over 200 viruses, spread by droplets and hands", ["200", "virus", "droplet", "hand", "surface"]], ["Virus enters through eyes or nose", ["eyes", "nose", "touch", "face"]], ["Soap and rubbing wash it off", ["soap", "wash", "twenty seconds", "20 seconds", "rub"]], ["Antibiotics kill bacteria, not viruses", ["antibiotic", "bacteria", "not virus", "resistance"]]],
    mcq: { q: "Why do antibiotics not help with a common cold?", o: ["Colds are caused by viruses and antibiotics only act on bacteria", "The cold virus lives in the nose where tablets cannot reach", "Antibiotics are too weak for colds", "They work, but only after a week"] },
    bring: "When someone asks the chemist for antibiotics for a cold: “A cold is a virus. Antibiotics are for bacteria. Soap and a week are the real treatment.”",
    follow: "How many things do you touch between the train and your face?",
    deeper: "The idea that cold weather causes colds is partly true. Rhinoviruses multiply better in the cooler air of the nose, and people crowd indoors in bad weather. But without the virus, no amount of cold gives you a cold." },

  { id: "hb-liver-alcohol", type: "scientific principle", domain: "science", title: "The liver and the path of a drink", value: 4, cue: "a party, a liver function test, or ‘black coffee to sober up’",
    emoji: "🫁", wiki: "Liver",
    fact: "The liver weighs about 1.5 kg and does more than 500 jobs: it stores sugar, makes proteins, cleans the blood and breaks down medicines and alcohol. It is the only internal organ that can regrow most of itself. It clears roughly one standard drink an hour, and nothing speeds that up.",
    why: "Coffee, cold showers and food do not sober anyone up. Only time does, because the liver works at a fixed pace.",
    mech: "Alcohol passes from the stomach and gut straight into the blood and reaches the brain within minutes. The liver breaks it down in two steps. First an enzyme turns it into acetaldehyde, a chemical more toxic than alcohol itself, which causes flushing and much of the hangover. A second enzyme turns that into acetate, which the body burns. The enzymes work at a nearly fixed speed, so drinking faster only raises the blood level. Over years, heavy drinking makes the liver store fat, then scar. Scarring, called cirrhosis, cannot be undone. Many Indians, like many East Asians, carry a slower second enzyme, so acetaldehyde builds up and the face flushes.",
    models: ["bottlenecks", "compounding"],
    q: "How does the body deal with alcohol, and why can nothing sober you up fast?",
    a: "Alcohol enters the blood quickly. The liver converts it first to toxic acetaldehyde, then to acetate, using enzymes that work at a fixed pace of about one drink an hour. Faster drinking only raises blood levels, and years of heavy drinking cause fat and then scarring.",
    chain: [["Alcohol enters blood and brain within minutes", ["blood", "brain", "minutes", "gut"]], ["Liver turns it into toxic acetaldehyde", ["acetaldehyde", "toxic", "enzyme", "flush"]], ["Then into acetate at a fixed pace", ["acetate", "fixed", "one drink", "hour", "pace"]], ["Years of heavy drinking cause fat then scarring", ["fat", "scar", "cirrhosis", "years"]]],
    mcq: { q: "Why does black coffee not sober a person up?", o: ["The liver clears alcohol at a fixed pace that coffee cannot change", "Coffee contains a little alcohol", "Coffee stops the stomach absorbing alcohol", "It does sober people up within minutes"] },
    bring: "When someone offers coffee to a drunk friend: “The liver clears about one drink an hour. Coffee just makes an awake drunk.”",
    follow: "Did you know the liver can regrow after a large part is removed?",
    deeper: "Because the liver regrows, a living person can donate part of it. Both pieces grow back to near full size within months. Fatty liver now also appears in people who never drink, often linked to diabetes and belly fat." },

  { id: "hb-kidneys", type: "scientific principle", domain: "science", title: "The kidneys filter 180 litres a day", value: 4, cue: "a dialysis centre, a creatinine report, or why doctors worry about sugar and BP together",
    emoji: "🫘", wiki: "Kidney",
    fact: "Your two kidneys are each the size of a fist. Together they filter about 180 litres of fluid from the blood every day, then take almost all of it back. Only 1 to 2 litres leave as urine. Each kidney has about a million tiny filters called nephrons.",
    why: "Kidneys are not just drains. They balance water, salt and acid, help control blood pressure, and tell the bone marrow to make red blood cells.",
    mech: "Blood arrives under pressure into a tangle of fine vessels in each nephron. Water, salt, sugar and waste are pushed out into a tube; cells and large proteins stay behind. Along the tube the body reabsorbs what it wants: nearly all the water, all the sugar, and salt as needed. Waste such as urea stays and becomes urine. Because the filters are so fine, they are easily damaged by high pressure and high sugar. Diabetes and high blood pressure are the two main causes of kidney failure. Damage is silent until most of the filters are gone, which is why kidney function is checked with a blood test.",
    models: ["margin-of-safety", "second-order-thinking"],
    q: "How do the kidneys clean the blood, and why do diabetes and high BP damage them?",
    a: "Each nephron pushes water, salt and waste out of the blood under pressure, then reabsorbs almost all the water and useful substances, leaving waste as urine. The filters are very fine, so high pressure and high sugar damage them silently until most are gone.",
    chain: [["Blood is pushed through a million fine filters", ["nephron", "million", "filter", "pressure", "pushed"]], ["Almost all water and useful things are taken back", ["reabsorb", "taken back", "take back", "180", "1 to 2"]], ["Waste leaves as urine", ["urea", "waste", "urine"]], ["High sugar and pressure silently destroy filters", ["diabetes", "high blood pressure", "damage", "silent", "fail"]]],
    mcq: { q: "Of about 180 litres filtered daily, how much becomes urine?", o: ["About 1 to 2 litres", "About 90 litres", "All 180 litres", "About 20 litres"] },
    bring: "When kidney disease comes up: “The kidneys filter 180 litres a day through a million tiny sieves. Sugar and pressure wear the sieves out.”",
    follow: "Did you know the kidneys also tell the body to make red blood cells?",
    deeper: "Dialysis does the filtering outside the body, usually three times a week for about four hours. It replaces only part of what a kidney does. Many painkillers of the aspirin family are hard on the kidneys when taken often, so long-term use should be discussed with a doctor." },

  { id: "hb-lungs", type: "scientific principle", domain: "science", title: "The lungs: a tennis court folded into your chest", value: 3, cue: "breathlessness on stairs, pollution masks, or how oxygen gets into blood",
    emoji: "🌬️", wiki: "Pulmonary alveolus",
    fact: "Your lungs end in about 300 to 500 million tiny air sacs called alveoli. Spread flat, their surface would cover roughly 50 to 75 square metres, often compared to a tennis court, though closer to half of one. You breathe about 20,000 times a day.",
    why: "Oxygen enters the blood only by seeping across a wall. To move enough of it, the body needs a huge wall folded into a small space.",
    mech: "Air passes down branching tubes that split more than twenty times, ending in clusters of alveoli like bunches of grapes. Each sac is wrapped in capillaries, blood vessels so thin that red cells pass in single file. The wall between air and blood is thinner than a sheet of paper. Oxygen seeps across into the blood and carbon dioxide seeps out, simply because each moves from where it is more to where it is less. A huge area and a very thin wall make this fast enough for life. Smoke and fine dust damage the sacs, and once destroyed they do not grow back.",
    models: ["first-principles", "bottlenecks"],
    q: "Why do the lungs need such a large surface area?",
    a: "Oxygen enters blood only by seeping across a thin wall from where there is more to where there is less. Hundreds of millions of alveoli wrapped in capillaries give 50 to 75 square metres of wall, so enough gas crosses with every breath.",
    chain: [["Air ends in hundreds of millions of alveoli", ["alveol", "million", "sac", "grape"]], ["Each sac is wrapped in thin capillaries", ["capillar", "thin", "single file", "wall"]], ["Gas seeps from more to less", ["seep", "more to", "less", "diffus", "cross"]], ["Huge area makes it fast enough", ["area", "square metres", "tennis", "50", "fast enough"]]],
    mcq: { q: "Why is the lungs' inner surface so large?", o: ["To let enough oxygen cross into the blood through a thin wall", "To store air for diving", "To warm the body", "To filter out all dust before it reaches blood"] },
    bring: "When someone is breathless on the stairs: “Inside your chest is half a tennis court of surface, folded into 500 million tiny sacs.”",
    follow: "What do you think happens to that surface after twenty years of smoking?",
    deeper: "Emphysema, common in long-term smokers, destroys the walls between alveoli. Fewer, bigger sacs mean less surface, so each breath carries less oxygen. The textbook figure for the surface area varies between 50 and 100 square metres depending on how it is measured." },

  { id: "hb-muscles-grow", type: "scientific principle", domain: "science", title: "How muscles grow: stress, repair, rest", value: 3, cue: "a new gym membership, protein powder, or sore legs after a trek",
    emoji: "💪", wiki: "Muscle hypertrophy",
    fact: "Muscles grow by making their existing fibres thicker, not by adding many new ones. Lifting a load heavier than usual signals the fibres to build more protein. The building happens during rest, over the next day or two, not during the workout.",
    why: "People think the gym builds the muscle. The gym only sends the order. Sleep and food fill it.",
    mech: "When a muscle works against a heavy load, the tension stretches its fibres and switches on genes for muscle protein building. The old idea that growth needs ‘micro-tears’ is only partly right: some fibre damage happens and is repaired, but tension itself seems to be the main signal. Over about 24 to 48 hours the fibres add protein and thicken. Protein from food supplies the bricks. If the same load is repeated, the muscle adapts and stops growing, so the load must slowly rise. From around the thirties, adults lose muscle each decade unless they load it, which is why strength matters more with age.",
    models: ["feedback-loops", "compounding"],
    q: "How does a muscle actually get bigger?",
    a: "Working against a heavy load creates tension that signals fibres to build protein. Over the next one to two days of rest the fibres thicken, using protein from food. The load must slowly rise or the muscle adapts and stops growing.",
    chain: [["Heavy load creates tension in the fibres", ["load", "tension", "heavier", "stretch"]], ["Signals switch on protein building", ["signal", "gene", "protein building", "order"]], ["Fibres thicken during rest over a day or two", ["rest", "thicken", "24", "48", "day or two", "sleep"]], ["Load must rise or growth stops", ["rise", "adapt", "stops growing", "progress"]]],
    mcq: { q: "When does muscle growth mainly happen?", o: ["During rest in the day or two after the workout", "In the middle of the workout", "Only while eating protein", "Only during sleep on the same night"] },
    bring: "When someone trains hard every day without rest: “The gym sends the order. The muscle is built while you sleep.”",
    follow: "Did you know adults start losing muscle from their thirties unless they use it?",
    deeper: "Soreness a day or two after exercise is not a measure of growth; people can grow without it and ache without growing. How much protein a person needs, and whether supplements are needed at all, depends on the person, which is a question for a doctor or a qualified dietitian." },

  { id: "hb-10000-steps", type: "fact", domain: "science", title: "10,000 steps came from a pedometer advertisement", value: 4, cue: "a step counter, a morning walk group, or a fitness band target",
    emoji: "🚶", wiki: "Pedometer",
    fact: "The 10,000 steps a day target did not come from science. It came from a Japanese pedometer sold in 1965 called manpo-kei, which means ‘10,000 steps meter’. The number was chosen because it sounded good. Recent research suggests most of the benefit comes by about 7,000 steps.",
    why: "A marketing slogan became a global health rule for sixty years before anyone measured it properly.",
    mech: "The Japanese character for 10,000 looks a little like a walking man, and the round number was memorable. Fitness bands later copied it. In 2025 a large review in The Lancet Public Health combined 57 studies that measured steps with devices. Compared with 2,000 steps a day, people walking about 7,000 had roughly half the risk of dying over the study periods and lower risks of heart disease, diabetes and dementia. Beyond 7,000 the benefits kept rising but much more slowly. The biggest gain was going from very little to some.",
    models: ["goodharts-law", "map-vs-territory"],
    q: "Where did the 10,000 steps rule come from, and what does the evidence now say?",
    a: "It came from a 1965 Japanese pedometer called manpo-kei, ‘10,000 steps meter’, a marketing name. A 2025 review of 57 studies found most benefit by about 7,000 steps compared with 2,000, with slower gains beyond that.",
    chain: [["A 1965 Japanese pedometer called manpo-kei", ["1965", "manpo", "pedometer", "japan", "advert", "marketing"]], ["The number was chosen for sound, not science", ["sound", "memorable", "not from science", "did not come", "chosen"]], ["Review found most benefit by about 7,000", ["7,000", "7000", "seven thousand", "review", "lancet"]], ["Gains slow beyond that, biggest gain from none to some", ["slow", "flatten", "beyond", "none to some", "very little"]]],
    mcq: { q: "Where did the 10,000 steps target come from?", o: ["A Japanese pedometer's marketing name in 1965", "A WHO guideline from 1980", "The average steps of Olympic athletes", "A study of Himalayan villagers"] },
    bring: "When someone feels guilty about 8,000 steps: “10,000 was a pedometer brand name from 1965. Studies now show most of the benefit by 7,000.”",
    follow: "How many steps does your normal day in Mumbai add up to?",
    deeper: "The 2025 review found that for some outcomes, like heart deaths and depression, benefits kept rising in a straight line, while for overall death and dementia they flattened near 5,000 to 7,000. Observational studies show links, not proof of cause, and the certainty was rated moderate." },

  { id: "hb-vitamin-d-india", type: "concept", domain: "science", region: "india", title: "Vitamin D deficiency in sunny India", value: 4, cue: "bone pain, a vitamin D report, or ‘we get so much sun’",
    emoji: "☀️", wiki: "Vitamin D deficiency",
    fact: "India has sun almost all year, yet studies find that most Indians tested have low vitamin D. Estimates range widely, from about a third to over 90% depending on the group studied, and city studies often find more than two-thirds.",
    why: "Sunlight is only the raw material. Skin, clothing, time of day, pollution and indoor life decide whether the body actually makes the vitamin.",
    mech: "Skin makes vitamin D when a specific part of sunlight, UVB, hits it. UVB is strongest around midday and is weak early in the morning, when many Indians take their walk. Darker skin has more melanin, which is natural sunscreen, so it needs longer in the sun to make the same amount. Clothing covers most skin, and city life keeps people indoors through the day. Air pollution and glass block UVB. Few Indian foods contain vitamin D. The vitamin helps the gut absorb calcium, so a lack of it weakens bones and may cause bone and muscle pain.",
    models: ["second-order-thinking", "map-vs-territory"],
    q: "Why do so many Indians lack vitamin D despite living in a sunny country?",
    a: "Skin makes vitamin D only from midday UVB. Darker skin needs longer, clothing covers skin, people are indoors through the day, and pollution blocks UVB. Few Indian foods supply it, so bones suffer from poor calcium absorption.",
    chain: [["Skin needs midday UVB to make vitamin D", ["uvb", "midday", "sunlight", "skin makes"]], ["Darker skin and clothing reduce what is made", ["melanin", "darker", "clothing", "cover", "longer"]], ["Indoor life and pollution block the sun", ["indoor", "pollution", "glass", "block"]], ["Low vitamin D means poor calcium and weak bones", ["calcium", "bone", "absorb", "weak"]]],
    mcq: { q: "Why does a morning walk at 7 am give little vitamin D?", o: ["UVB rays are weak early and strongest around midday", "The body only makes vitamin D at night", "Morning air has too much oxygen", "Vitamin D needs cloudy skies"] },
    bring: "When someone says Indians cannot lack vitamin D: “Sun is not enough. You need midday sun on bare skin, and Mumbai life gives us almost none of that.”",
    follow: "How many minutes of midday sun does your skin see in a normal week?",
    deeper: "Different labs and countries use different cut-offs for ‘deficient’, which is one reason estimates vary so much. Taking vitamin D tablets without a test can be unhelpful or, in large doses, harmful. Whether you need testing or supplements is a question for a doctor." },

  { id: "hb-anaemia-india", type: "concept", domain: "science", region: "india", title: "Anaemia: why half of Indian women lack iron", value: 4, cue: "tiredness, pale skin, a haemoglobin test, or why iron is added to rice",
    emoji: "🥬", wiki: "Iron-deficiency anemia",
    fact: "India's national health survey of 2019 to 2021 found that about 57% of women aged 15 to 49 and 67% of children under five were anaemic. Anaemia means too few healthy red blood cells, most often because of too little iron.",
    why: "Anaemia makes a person tired, breathless and slow to learn. In children it affects brain growth. It is one of India's largest and quietest health problems.",
    mech: "Red blood cells carry oxygen using haemoglobin, and haemoglobin needs iron at its centre. With too little iron, the body makes fewer and smaller red cells, so tissues get less oxygen and the person tires easily. Iron from meat is absorbed well; iron from plants is absorbed poorly, and many Indian diets are mostly plant-based. Tea and coffee with meals block iron absorption further, while vitamin C helps it. Women lose iron every month through menstruation and more in pregnancy. Worm infections and malaria also drain it. The government now adds iron to rice and salt in some schemes.",
    models: ["bottlenecks", "second-order-thinking"],
    q: "Why is anaemia so common in India, and what does iron do in the body?",
    a: "Iron sits at the centre of haemoglobin, which carries oxygen. Many Indian diets are plant-based, and plant iron absorbs poorly, worse with tea at meals. Women lose iron monthly and in pregnancy, and worms add to it. So about 57% of women are anaemic.",
    chain: [["Iron is needed for haemoglobin to carry oxygen", ["haemoglobin", "hemoglobin", "oxygen", "iron"]], ["Plant iron absorbs poorly, tea blocks it", ["plant", "absorb", "tea", "vitamin c"]], ["Women lose iron monthly and in pregnancy", ["menstruat", "monthly", "pregnan", "lose"]], ["Result: about 57% of women are anaemic", ["57", "half", "women", "survey"]]],
    mcq: { q: "What does iron do in the blood?", o: ["It sits in haemoglobin and lets red cells carry oxygen", "It makes blood clot", "It fights viruses", "It gives blood its salty taste"] },
    bring: "When someone is always tired: “More than half of Indian women are anaemic. Iron is the atom that carries oxygen, and our diets are short of it.”",
    follow: "Did you know drinking chai with a meal reduces the iron you absorb from it?",
    deeper: "The survey measured haemoglobin with a finger-prick test, and some scientists argue this over-counts anaemia compared with a vein sample. Even so, the problem is real and large. Tiredness has many causes, so a blood test and a doctor, not self-prescribed iron, is the right path." },

  { id: "hb-tobacco-gutka", type: "fact", domain: "science", region: "india", title: "Tobacco in India: 13 lakh deaths a year and the gutka problem", value: 5, cue: "a paan shop, red stains on a wall, or someone saying they only chew, not smoke",
    emoji: "🚭", wiki: "Gutka",
    fact: "Tobacco kills an estimated 13 lakh people in India every year. The 2016 to 2017 national survey found 28.6% of adults use tobacco, and more of them chew it than smoke it. India has among the highest rates of mouth cancer in the world, largely because of chewed tobacco and gutka.",
    why: "Many believe chewing is the safe option. The evidence says the opposite: it is the main cause of India's mouth cancer burden.",
    mech: "Tobacco smoke contains at least 69 chemicals known to cause cancer, plus carbon monoxide that starves tissues of oxygen and tar that damages the lungs. Nicotine itself is what makes quitting hard: it reaches the brain in seconds and rewires its reward system. Chewed tobacco presses these chemicals against the cheek and gum for hours at a time. Gutka adds areca nut, which is itself classed as a cause of cancer and hardens the mouth tissue so that it cannot open fully. The cells lining the cheek are damaged again and again, and over years some turn cancerous. Most states banned gutka from 2012 onward, but it is still sold widely.",
    models: ["incentives", "compounding"],
    q: "Why is chewing tobacco not safer than smoking, and how does tobacco harm the body?",
    a: "Tobacco carries dozens of cancer-causing chemicals and nicotine that hooks the brain. Chewing presses them against the cheek for hours, and gutka's areca nut itself causes cancer. That is why India has very high mouth cancer rates despite most states banning gutka since 2012.",
    chain: [["Tobacco has dozens of cancer-causing chemicals", ["69", "chemical", "cancer-causing", "carcinogen", "tar"]], ["Nicotine hooks the brain in seconds", ["nicotine", "brain", "addict", "hook", "quit"]], ["Chewing presses it on the cheek; areca adds harm", ["chew", "cheek", "gum", "areca", "gutka"]], ["India's high mouth cancer rates; bans since 2012", ["mouth cancer", "oral cancer", "2012", "ban"]]],
    mcq: { q: "Why does India have such high rates of mouth cancer?", o: ["Widespread chewing of tobacco and gutka", "Too much spicy food", "Air pollution", "Lack of toothpaste"] },
    bring: "When someone says they only chew: “Chewing is the main reason India leads the world in mouth cancer. The areca nut alone is a cancer cause.”",
    follow: "Have you ever seen the white patches a doctor looks for inside a chewer's cheek?",
    deeper: "The 13 lakh figure is a WHO estimate and includes deaths from heart disease and lung disease, not only cancer. Quitting at any age cuts the risk, and the body begins to repair within weeks. Doctors and the national quitline can help; nicotine is a true addiction, not a weakness." },

  { id: "hb-air-pollution", type: "concept", domain: "science", region: "india", title: "PM2.5: the dust that gets into your blood", value: 5, cue: "a hazy winter morning, AQI numbers on the phone, or Delhi's smog news",
    emoji: "🌫️", wiki: "Particulates",
    fact: "PM2.5 means particles smaller than 2.5 micrometres, about one thirtieth the width of a hair. The WHO's guideline for the yearly average is 5 micrograms per cubic metre. Delhi's 2024 average was about 105. Mumbai is cleaner thanks to the sea breeze but still well above the guideline, especially in winter.",
    why: "Big dust is caught by the nose. PM2.5 is small enough to reach the deepest part of the lungs and pass into the blood, which is why it harms the heart as much as the lungs.",
    mech: "These particles come from vehicle exhaust, construction dust, burning rubbish and crop stubble, and industry. In winter, cold air sits near the ground like a lid and traps them. Breathed in, the smallest particles reach the alveoli and cross into the bloodstream. There they cause inflammation in blood vessels, which raises blood pressure and makes clots more likely. Long exposure is linked to heart attacks, strokes, lung disease and lower birth weight. A 2020 estimate in The Lancet put air pollution deaths in India at about 17 lakh in 2019. Mumbai's sea wind often clears the air by afternoon, but construction and traffic keep winter levels high.",
    models: ["second-order-thinking", "margin-of-safety"],
    q: "What is PM2.5 and why does it harm the heart, not just the lungs?",
    a: "PM2.5 is dust smaller than 2.5 micrometres from exhaust, construction and burning. It is small enough to reach the alveoli and cross into the blood, where it inflames vessels and raises the risk of heart attacks and strokes. Winter air traps it, and India's deaths are estimated at about 17 lakh a year.",
    chain: [["Tiny particles from exhaust, dust and burning", ["2.5", "exhaust", "construction", "burn", "stubble"]], ["Small enough to reach alveoli and enter blood", ["alveol", "blood", "deep", "cross"]], ["Inflames vessels, raising heart and stroke risk", ["inflam", "heart", "stroke", "clot", "pressure"]], ["Winter traps it; huge death toll", ["winter", "trap", "lid", "17 lakh", "1.67 million", "deaths"]]],
    mcq: { q: "Why is PM2.5 more dangerous than larger dust?", o: ["It is small enough to reach deep into the lungs and pass into the blood", "It is more acidic", "It is heavier and settles in the stomach", "It carries more bacteria"] },
    bring: "On a hazy morning: “PM2.5 is dust so fine it enters the blood. That is why bad air causes heart attacks, not only coughs.”",
    follow: "Have you noticed how Mumbai's air clears when the sea breeze picks up in the afternoon?",
    deeper: "India's own standard for yearly PM2.5 is 40, eight times the WHO guideline, and most Indian cities still exceed even that. Indoor smoke from wood and dung stoves is a major source for rural families, which is one reason LPG connections are a health programme as well as an energy one." },

  { id: "hb-myopia-screens", type: "concept", domain: "science", title: "Why more children need glasses", value: 4, cue: "a child's new spectacles, screen-time arguments, or thick glasses in a classroom",
    emoji: "👓", wiki: "Near-sightedness",
    fact: "Myopia, or short sight, is rising fast. In urban Indian children it rose from about 4% in 1999 to about 21% in 2019. In parts of East Asia, 80 to 90% of young adults are now short-sighted. A 2016 study predicted that half the world's population will be myopic by 2050.",
    why: "Genes have not changed in twenty years. Childhood has. The best-supported cause is not screens themselves but the hours spent indoors.",
    mech: "In myopia the eyeball grows slightly too long, so distant light focuses in front of the retina and far things blur. Eye growth is guided by light and focus during childhood. Bright outdoor light seems to release signals in the retina that slow this growth. Children who spend about two hours a day outdoors get myopia less often, in several studies. Hours of close work, whether books or phones, may add to the risk, but the evidence for screens on their own is weaker than for time indoors. Once the eyeball has lengthened, glasses correct the blur but do not shorten the eye.",
    models: ["second-order-thinking", "confirmation-bias"],
    q: "Why are so many more children becoming short-sighted, and what does the evidence point to?",
    a: "The eyeball grows too long so distant things blur. Bright outdoor light slows eye growth in childhood, and children now spend far more time indoors. Close work may add risk, but the evidence for time indoors is stronger than for screens alone. Urban Indian children went from 4% to 21% in twenty years.",
    chain: [["The eyeball grows too long, so far things blur", ["eyeball", "too long", "retina", "blur", "focus"]], ["Outdoor light slows eye growth", ["outdoor", "bright", "light", "slow", "two hours"]], ["Children spend more time indoors doing close work", ["indoor", "close work", "screen", "phone", "book"]], ["Rapid rise: 4% to 21% in urban India", ["4%", "21%", "1999", "2019", "rise", "rising"]]],
    mcq: { q: "Which factor has the strongest evidence for protecting children from myopia?", o: ["Time spent outdoors in daylight", "Eating carrots", "Watching television from far away", "Wearing sunglasses indoors"] },
    bring: "When parents argue about screen time: “The strongest evidence is not about the screen. It is about daylight. Children indoors get short-sighted.”",
    follow: "How many hours a day did you spend outside as a child, and how many does a child you know spend now?",
    deeper: "Taiwan made schools send children outdoors for two hours a day from 2010, and myopia rates in its primary schools fell afterwards, which supports the daylight idea. Strong myopia raises the risk of retinal problems later in life, so it is more than an inconvenience. An eye doctor should guide any child's care." },

  { id: "hb-earphones", type: "fact", domain: "science", title: "Hearing loss from earphones: the 60/60 rule", value: 4, cue: "loud music on the train, a friend who always says ‘what?’, or ringing in the ears after a wedding",
    emoji: "🎧", wiki: "Noise-induced hearing loss",
    fact: "The WHO estimates that over 100 crore young people are at risk of hearing loss from loud personal audio and loud venues. Sound at 85 decibels is safe for about eight hours a day. At 100 decibels, the level of many earphones at full volume, the safe time is about 15 minutes.",
    why: "Hearing loss from noise is permanent. The cells that are destroyed do not grow back, and the loss creeps in so slowly that people notice it years late.",
    mech: "Inside the inner ear, about 15,000 tiny hair cells turn vibrations into nerve signals. Loud sound bends them too hard and too often. After a loud night they are tired and bent, which is the ringing or muffled feeling. With rest they recover. With repeated loud exposure they die, and in humans they are never replaced. High-pitched hearing goes first, which is why speech in a noisy room becomes hard to follow. Every 3 decibel rise doubles the sound energy, so a small turn of the volume knob halves the safe time. A simple guide is 60/60: no more than 60% volume for no more than 60 minutes at a stretch.",
    models: ["compounding", "margin-of-safety"],
    q: "How does loud sound damage hearing, and what is a safe listening rule?",
    a: "Loud sound bends the inner ear's hair cells too hard; with repeated exposure they die and never grow back. Every 3 decibels doubles the energy, so 85 dB is safe for eight hours but 100 dB for only 15 minutes. The 60/60 rule means 60% volume for 60 minutes.",
    chain: [["Hair cells in the inner ear turn vibration into signals", ["hair cell", "inner ear", "vibration", "15,000"]], ["Loud sound bends them; repeated exposure kills them", ["bend", "die", "destroy", "repeated", "never grow back", "never replaced"]], ["Each 3 decibels doubles the energy and halves safe time", ["3 decibel", "double", "85", "100", "15 minutes", "eight hours"]], ["60/60 rule: 60% volume, 60 minutes", ["60/60", "60%", "60 minutes", "sixty"]]],
    mcq: { q: "What happens to the ear's hair cells after repeated loud noise?", o: ["They die and are never replaced", "They grow thicker to protect the ear", "They regrow after a week of silence", "They move deeper into the ear"] },
    bring: "When someone's music is audible from their earphones on the train: “If I can hear it, it is probably over 85 decibels. The hair cells that die never come back.”",
    follow: "Do you ever notice ringing in your ears after a loud event?",
    deeper: "A busy Mumbai road often measures 80 decibels or more, and festival loudspeakers can pass 100. Ringing after a loud event means the hair cells were overloaded. If ringing or muffled hearing lasts more than a day, an ear doctor should check it." },

  { id: "hb-depression", type: "concept", domain: "science", title: "Depression is an illness, not a weakness", value: 5, cue: "someone who ‘has lost interest in everything’, a friend who says just be positive, or mental health news",
    emoji: "🌧️", wiki: "Major depressive disorder",
    fact: "Depression is a medical condition in which low mood, loss of interest and loss of energy last for weeks and change how a person sleeps, eats, thinks and works. The WHO estimates about 28 crore people worldwide live with it. India's national mental health survey of 2015 to 2016 found roughly one in twenty adults had suffered depression.",
    why: "It is one of the most common illnesses in India and one of the least talked about. Most people with it never see a doctor, yet it is treatable.",
    mech: "Depression is not ordinary sadness. Sadness has a cause and lifts. Depression lasts at least two weeks, drains interest from things once enjoyed, and often brings poor sleep, slowed thinking and guilt without reason. Brain scans show changes in the circuits that handle mood and reward, and stress hormones stay high. Genes, long stress, loss, illness and isolation all raise the risk. Treatments that work in trials include talking therapy, medicines and exercise, often together. Telling someone to cheer up does not work, for the same reason it does not cure a fever. A doctor or counsellor can diagnose and treat it.",
    models: ["map-vs-territory", "inversion"],
    q: "How is depression different from sadness, and why is it treated as an illness?",
    a: "Sadness has a cause and passes. Depression lasts weeks, removes interest and energy and changes sleep and thinking, with measurable changes in brain circuits and stress hormones. Genes, stress and isolation raise the risk. Talking therapy and medicines help, so a doctor should be involved.",
    chain: [["Lasts weeks and removes interest and energy", ["weeks", "interest", "energy", "sleep", "two weeks"]], ["Measurable changes in brain circuits and stress hormones", ["brain", "circuit", "hormone", "scan", "measurable"]], ["Genes, stress, loss and isolation raise the risk", ["gene", "stress", "loss", "isolation", "risk"]], ["Treatable with therapy and medicines; see a doctor", ["therapy", "medicine", "treat", "doctor", "counsellor"]]],
    mcq: { q: "What separates depression from ordinary sadness?", o: ["It lasts for weeks and removes interest and energy across life", "It only happens after a death", "It always has an obvious cause", "It passes within a day or two"] },
    bring: "When someone says a depressed person should just stay positive: “Depression is an illness with changes you can see on a brain scan. Cheer up works as well as it does on a fever.”",
    follow: "Why do you think we find it easier to talk about diabetes than about depression?",
    deeper: "India runs a free, round-the-clock mental health helpline called Tele-MANAS, reached on 14416. If anyone speaks of ending their life, take it seriously and get them to a doctor or helpline immediately. Treatment choices belong with a doctor." },

  { id: "hb-meditation", type: "concept", domain: "science", title: "Meditation: what the measurements show", value: 3, cue: "a meditation app, Vipassana courses, or claims that meditation cures everything",
    emoji: "🧘", wiki: "Meditation",
    fact: "In 2014 researchers at Johns Hopkins reviewed 47 well-controlled trials of meditation with about 3,500 people. Mindfulness meditation gave small to moderate improvements in anxiety, depression and pain, about as much as other active treatments like exercise. There was no good evidence for effects on sleep, attention or weight.",
    why: "Both the fans and the sceptics are partly right. Meditation helps, measurably, and modestly. It is not magic.",
    mech: "Meditation trains attention: noticing a thought or feeling and returning to the breath, again and again. Over weeks this seems to weaken the automatic loop in which a worry triggers another worry. Brain scans show changes in attention and emotion networks in people who practise regularly, though the studies are small. The best trials compared meditation with another active programme, not with doing nothing, which is why the effects look modest. Many popular claims rest on weaker studies without such comparison. The honest summary is a real but small benefit for stress, low mood and pain for people who keep practising.",
    models: ["bayesian-thinking", "confirmation-bias"],
    q: "What does good evidence say meditation does and does not do?",
    a: "A 2014 review of 47 controlled trials found small to moderate gains in anxiety, depression and pain, similar to other active treatments, and no good evidence for sleep, attention or weight. Meditation trains attention and weakens worry loops, but the measured benefit is modest.",
    chain: [["47 controlled trials reviewed in 2014", ["47", "2014", "johns hopkins", "review", "trial"]], ["Small to moderate gains in anxiety, depression and pain", ["anxiety", "depression", "pain", "moderate", "small"]], ["Similar to other active treatments; no evidence for sleep or weight", ["exercise", "active", "sleep", "weight", "no good evidence", "attention"]], ["It trains attention and weakens worry loops", ["attention", "breath", "loop", "worry", "train"]]],
    mcq: { q: "According to the 2014 Johns Hopkins review, how large were meditation's effects on anxiety and depression?", o: ["Small to moderate, similar to other active treatments", "Larger than any medicine", "Zero", "Large for sleep, small for anxiety"] },
    bring: "When someone says meditation cures everything or nothing: “The best review found a real but modest effect on anxiety, low mood and pain. Nothing for sleep or weight.”",
    follow: "Have you ever tried sitting still for ten minutes and counting your breaths?",
    deeper: "A few people report unpleasant experiences during intense retreats, which research is only now cataloguing. Meditation is a useful tool, not a replacement for treatment when someone is ill, and anyone with depression or anxiety should also speak to a doctor." },

  { id: "hb-john-snow", type: "historical story", domain: "science", title: "John Snow and the Broad Street pump", value: 5, cue: "cholera, dirty water, or how data solved a mystery", story: "hb-snow",
    emoji: "🗺️", wiki: "1854 Broad Street cholera outbreak",
    fact: "In 1854 cholera killed more than 500 people in ten days around Broad Street in London. Doctors blamed bad air. Dr John Snow marked each death on a map and saw they clustered around one water pump. On 8 September the pump handle was removed. His work founded the science of epidemiology.",
    why: "Snow found the cause of a disease thirty years before anyone saw the germ, using only a map, a list and careful questions.",
    mech: "Snow believed cholera spread through something swallowed, because it attacked the gut, not the lungs. He walked the streets asking where each dead person had drunk water. A brewery nearby lost no workers; they drank beer. A workhouse with its own well was spared. A widow far away in Hampstead died, and her son told Snow she had water carted from Broad Street because she liked its taste. The pattern pointed to one pump. Later a priest found that a baby's diapers had been washed into a cesspit leaking into the well. The germ itself, Vibrio cholerae, was identified by Robert Koch in 1883.",
    models: ["first-principles", "bayesian-thinking", "map-vs-territory"],
    q: "How did John Snow find the cause of the 1854 cholera outbreak?",
    a: "He mapped every death and saw them cluster around the Broad Street pump. Brewery workers who drank beer were spared, and a widow in Hampstead who had the pump's water carted to her died. The handle was removed on 8 September, long before the germ was known.",
    chain: [["Deaths were mapped and clustered around one pump", ["map", "cluster", "pump", "broad street"]], ["Exceptions confirmed it: brewery, Hampstead widow", ["brewery", "beer", "hampstead", "widow", "workhouse"]], ["The pump handle was removed on 8 September", ["handle", "removed", "8 september"]], ["The germ was found only decades later", ["koch", "1883", "germ", "decades", "thirty years"]]],
    mcq: { q: "What did John Snow identify as the source of the 1854 Soho cholera outbreak?", o: ["Water from the Broad Street pump", "Bad air from the Thames", "Rotten meat in the market", "Rats in the cellars"] },
    bring: "When someone solves a problem with data: “John Snow stopped cholera with a map and a pump handle, thirty years before anyone saw the germ.”",
    follow: "What problem around us might a simple map of cases reveal?",
    deeper: "The pump handle is now a symbol of public health; a replica stands on the street, which was renamed Broadwick Street. Snow was also a pioneer of anaesthesia, giving Queen Victoria chloroform at the birth of her eighth child in 1853." },

  { id: "hb-insulin-discovery", type: "historical story", domain: "science", title: "Insulin: the discovery sold for one dollar", value: 5, cue: "insulin prices, a diabetic relative's injections, or scientists who refused to get rich", story: "hb-insulin",
    emoji: "💉", wiki: "Frederick Banting",
    fact: "Before 1922, a child with type 1 diabetes usually died within a year or two. In 1921 and 1922 in Toronto, Frederick Banting, Charles Best, James Collip and John Macleod extracted insulin from animal pancreases. The first child treated, Leonard Thompson, recovered in January 1922. The discoverers sold the patent to the university for one dollar each.",
    why: "A hundred years later, insulin keeps millions of people alive, including lakhs in India. Its inventors deliberately chose not to profit from it.",
    mech: "Doctors knew the pancreas was involved: remove it from a dog and the dog got diabetes. But the pancreas also makes digestive juices that destroyed the hormone during extraction. Banting, a young surgeon with no research record, had the idea of tying off the pancreas duct so the juice-making cells died while the hormone-making cells survived. Macleod gave him a lab and a student, Best. Their crude extract lowered blood sugar in dogs. Collip, a biochemist, purified it enough for humans. Thompson's first injection on 11 January 1922 failed; Collip's purer extract on 23 January worked. Banting and Macleod received the Nobel Prize in 1923 and shared the money with Best and Collip.",
    models: ["first-principles", "incentives"],
    q: "How was insulin discovered, and what did its discoverers do with the patent?",
    a: "Banting tied off the pancreas duct so digestive cells died but hormone cells survived, Best helped extract it, and Collip purified it. Leonard Thompson recovered in January 1922. They sold the patent to the University of Toronto for one dollar each.",
    chain: [["The pancreas makes insulin but also juices that destroy it", ["pancreas", "digestive", "juice", "destroy"]], ["Banting tied the duct; Best and Collip extracted and purified", ["banting", "best", "collip", "duct", "purif"]], ["Leonard Thompson recovered in January 1922", ["thompson", "1922", "january", "first child", "recover"]], ["Patent sold for one dollar each", ["one dollar", "1 dollar", "patent", "sold"]]],
    mcq: { q: "What did insulin's discoverers do with the patent?", o: ["Sold it to the University of Toronto for one dollar each", "Sold it to a drug company for millions", "Kept it secret", "Gave it to the Canadian army"] },
    bring: "When drug prices come up: “Insulin's discoverers sold the patent for one dollar so it would stay cheap. A hundred years later the price fight continues.”",
    follow: "Would you have sold a discovery like that for one dollar?",
    deeper: "Banting is said to have felt that a doctor should not profit from a discovery that saved lives. Insulin from pigs and cows was used for sixty years. In 1982 insulin made by genetically engineered bacteria became the first such medicine approved for humans." },

  { id: "hb-ors", type: "historical story", domain: "science", region: "india", title: "ORS: sugar, salt and water that saved 5 crore lives", value: 5, cue: "a child with diarrhoea, an ORS packet at the chemist, or cheap things that work", story: "hb-ors",
    emoji: "🥤", wiki: "Oral rehydration therapy",
    fact: "Oral rehydration solution, ORS, is clean water with a measured amount of sugar and salt. In 1978 The Lancet called the science behind it ‘potentially the most important medical advance this century’. It was proven in Dhaka and Kolkata, and in 1971 in refugee camps near Bangaon, where Dr Dilip Mahalanabis used it to cut cholera deaths from about 30% to about 3%.",
    why: "Diarrhoea killed millions of children a year by draining their water. A drink costing a few rupees, that a mother can give at home, changed that.",
    mech: "In cholera and other diarrhoeas, the gut pours out water and salt faster than a person can drink it, and plain water is not absorbed well. In the 1960s scientists found that the gut has a pump that takes in salt and water together with glucose. Add sugar to salt water in the right ratio and the gut absorbs it even during cholera. Trials in Dhaka in 1968 showed it worked. In 1971 the Bangladesh war sent lakhs of refugees into camps in West Bengal, where intravenous fluid ran out. Mahalanabis mixed ORS in drums and let families give it by mouth. Deaths fell sharply. The WHO adopted ORS in the 1970s, and it is often estimated to have saved more than 5 crore lives.",
    models: ["first-principles", "bottlenecks", "inversion"],
    q: "How does ORS work, and how was it proven?",
    a: "The gut absorbs salt and water together with glucose, so sugar added to salt water is taken up even in cholera. Dhaka trials in 1968 showed this. In the 1971 refugee camps near Bangaon, Mahalanabis used it when IV fluid ran out and deaths fell from about 30% to about 3%. The Lancet called it the century's most important advance.",
    chain: [["Diarrhoea drains water and salt faster than plain water is absorbed", ["drain", "pour", "plain water", "lose", "faster"]], ["The gut absorbs salt and water together with glucose", ["glucose", "together", "pump", "ratio", "sugar"]], ["Proven in Dhaka, then in the 1971 Bangaon camps", ["dhaka", "1968", "1971", "bangaon", "mahalanabis", "refugee"]], ["Deaths fell from about 30% to 3%; 5 crore lives saved", ["30%", "3%", "5 crore", "50 million", "lancet"]]],
    mcq: { q: "Why does adding sugar to salt water help a person with cholera?", o: ["The gut absorbs salt and water together with glucose", "Sugar kills the cholera bacteria", "Sugar makes the drink taste better so children drink more", "Sugar thickens the stool"] },
    bring: "When someone dismisses simple solutions: “ORS is sugar, salt and water. The Lancet called it the most important medical advance of the century.”",
    follow: "Why do you think it took years for doctors to accept something so simple?",
    deeper: "The Kolkata and Dhaka cholera laboratories had worked on the science through the 1960s, and Robert Crane's discovery of the sugar-salt transporter in 1960 gave the mechanism. Dr Mahalanabis received the Padma Vibhushan in 2023, after his death in 2022. ORS is for replacing fluid; a child with severe diarrhoea or blood in the stool needs a doctor." }
  ]));

  MV.STORIES.push(
    { id: "hb-snow", assetId: "hb-john-snow", title: "The Map and the Pump Handle",
      hook: "In ten days of September 1854, more than 500 people died within a few streets of London. The cause was in plain sight, and only one doctor looked.",
      setting: "Soho, London, late summer 1854. Crowded houses, cesspits under the floors, and street pumps where families drew their water. Cholera had already killed tens of thousands in Britain.",
      character: "Dr John Snow, a quiet physician who did not drink alcohol and had given Queen Victoria anaesthesia. He believed cholera was swallowed, not breathed. Almost every other doctor believed in bad air, or miasma.",
      conflict: "The outbreak around Broad Street was the worst Snow had seen. If he was right about water, the killer was one pump. If he was wrong, removing it would do nothing and he would be mocked.",
      surprise: "Snow walked door to door and marked each death on a map. Deaths clustered around the Broad Street pump. The brewery beside it lost no workers; they drank the beer they made. A workhouse with its own well was spared. A widow in Hampstead, far away, died: her son said she had Broad Street water carted to her because she loved its taste.",
      turning: "On the evening of 7 September Snow put his map before the parish board. The next day, 8 September, they removed the pump handle. The outbreak, already fading, ended.",
      payoff: "A local priest, Henry Whitehead, set out to prove Snow wrong and instead found the source: a baby's soiled nappies washed into a cesspit that leaked into the well. The germ itself was not identified until Robert Koch saw Vibrio cholerae in 1883.",
      meaning: "Snow found the cause without seeing it, by asking where each person had drunk and letting the pattern speak. The method he used, counting cases and comparing groups, is how public health still works.",
      extra: ["Snow also compared two water companies across London and found far more deaths among customers of the one that drew water downstream of the sewers.", "The street is now Broadwick Street, and a pump without a handle stands there as a memorial.", "Bombay's own cholera and water troubles led to Vihar Lake in 1860, the city's first piped supply."],
      facts: [["1854"], ["broad street", "pump"], ["map"], ["brewery", "beer", "hampstead", "widow"], ["handle", "8 september"], ["bad air", "miasma"], ["koch", "1883", "germ"]],
      vocab: ["epidemiology", "cluster", "cesspit"] },

    { id: "hb-insulin", assetId: "hb-insulin-discovery", title: "The Patent Sold for One Dollar",
      hook: "In 1921 a failed surgeon with no research experience walked into a Toronto lab with one idea. Within eighteen months, children who were starving to death were walking out of hospital.",
      setting: "Toronto, Canada, summer 1921. Children with type 1 diabetes are kept alive for a few months on starvation diets and then die. Doctors know the pancreas is involved but cannot extract whatever it makes.",
      character: "Frederick Banting, a young surgeon whose practice had failed. Charles Best, a 22-year-old student who won the job on a coin toss. John Macleod, the professor who lent them a lab. James Collip, a biochemist who could purify things.",
      conflict: "The pancreas makes a hormone that controls sugar, but it also makes digestive juices that destroy that hormone the moment the gland is ground up. Every extraction had failed.",
      surprise: "Banting's idea: tie off the pancreas duct in dogs. The juice-making cells wither, the hormone-making islets survive. Working through a hot summer, he and Best made an extract that lowered the blood sugar of diabetic dogs. Then Collip purified it enough for a human.",
      turning: "On 11 January 1922 fourteen-year-old Leonard Thompson got the first injection. It barely worked and caused an abscess. On 23 January Collip's purer extract was given. His sugar fell to normal. Within weeks a ward of dying children was sitting up.",
      payoff: "Banting and Macleod won the Nobel Prize in 1923, and each shared his money with Best and Collip. Banting, Best and Collip sold the patent to the University of Toronto for one dollar each, so that insulin could be made cheaply for everyone.",
      meaning: "The science was a clever idea tested quickly. The choice that mattered as much was moral: the discoverers refused to own a medicine that children needed to live.",
      extra: ["Banting was furious at having to share the prize with Macleod and gave half his money to Best; Macleod then gave half of his to Collip.", "Leonard Thompson lived another thirteen years on insulin and died of pneumonia at 27.", "A century later, insulin pricing is still a political fight in several countries, which is why the one-dollar sale is remembered."],
      facts: [["1921", "1922"], ["toronto"], ["banting"], ["best", "collip"], ["duct", "digestive"], ["thompson", "leonard"], ["one dollar", "patent"], ["nobel", "1923"]],
      vocab: ["pancreas", "extract", "patent"] },

    { id: "hb-ors", assetId: "hb-ors", title: "Sugar, Salt and Water",
      hook: "In 1971 a doctor in a refugee camp ran out of intravenous fluid while cholera was killing a third of his patients. He mixed sugar and salt into drums of water, and the dying began to live.",
      setting: "Bangaon, West Bengal, 1971. Lakhs of refugees from the Bangladesh war crowd into camps during the monsoon. Cholera spreads through the camps. The standard treatment is fluid through a vein, which needs trained staff, sterile needles and supplies that are running out.",
      character: "Dr Dilip Mahalanabis, a Kolkata paediatrician working with the Johns Hopkins cholera research centre, with a handful of staff and thousands of patients.",
      conflict: "Scientists in Dhaka and Kolkata had shown in the 1960s that the gut absorbs salt and water together with glucose, so a sugar-salt drink could rehydrate even a cholera patient. Trials in Dhaka in 1968 had worked. But most doctors did not trust untrained families to give fluid by mouth, and no one had tried it on a disaster scale.",
      surprise: "Mahalanabis had the solution mixed in large drums and handed to patients and their relatives to drink freely. Family members, not nurses, did the work. In his camp the death rate fell to about 3%. In camps that relied on intravenous fluid alone it stayed around 20 to 30%.",
      turning: "The results were published and the World Health Organization adopted oral rehydration as its standard treatment for diarrhoea in the 1970s. Packets of pre-measured salts spread across the world.",
      payoff: "In 1978 The Lancet wrote that the discovery behind it was ‘potentially the most important medical advance this century’. ORS is often estimated to have saved more than 5 crore lives, most of them children, at a cost of a few rupees each.",
      meaning: "The most powerful medical tools are not always the most advanced. A cheap drink that a mother can give at home beat a hospital treatment that most of the world could not reach.",
      extra: ["The science began with Robert Crane's 1960 discovery that the gut carries sugar and salt through the same door.", "Dr Mahalanabis died in October 2022, and was awarded the Padma Vibhushan, India's second highest civilian honour, in 2023.", "Deaths of children from diarrhoea fell from several million a year in 1980 to well under a million today, with ORS a major reason."],
      facts: [["1971"], ["bangaon", "west bengal", "refugee"], ["mahalanabis"], ["dhaka", "kolkata", "1968"], ["glucose", "sugar and salt", "sugar-salt"], ["3%", "20 to 30%"], ["lancet", "most important medical advance"], ["5 crore", "world health organization", "who "]],
      vocab: ["rehydration", "intravenous", "absorption"] }
  );

